function renderCityRoute(section,t){const points=t.stops.filter(s=>s.coord);if(points.length<2)return;const width=500,height=600;const projection=d3.geoMercator().fitExtent([[70,70],[430,520]],{type:'MultiPoint',coordinates:points.map(s=>s.coord)});const line=d3.line().curve(d3.curveCatmullRom.alpha(.3))(points.map(s=>projection(s.coord)));const el=document.createElementNS('http://www.w3.org/2000/svg','svg');el.setAttribute('viewBox',`0 0 ${width} ${height}`);el.classList.add('route-overlay');el.innerHTML=`<path d="${line}"/>${points.map((s,i)=>{const p=projection(s.coord);return `<circle cx="${p[0]}" cy="${p[1]}" r="12"/><text x="${p[0]}" y="${p[1]+4}">${i+1}</text>`;}).join('')}`;section.querySelector('.chapter-visual').append(el);const hint=document.createElement('p');hint.className='hint play-stop-note';hint.textContent='站点顺序示意 · 城市海报底图未作地理配准';section.querySelector('.chapter-copy').append(hint);}
function tick(now){if(!playback.running)return;if(!playback.paused&&playback.ready){let elapsed=playback.elapsed+now-playback.start;if(playback.video){const scene=playback.scenes[playback.index];if(playback.video.readyState<2){playback.start=now;elapsed=playback.elapsed;}else elapsed=Math.max(0,(playback.video.currentTime-(scene.media.start||0))*1000);}const p=Math.min(1,elapsed/playback.duration);$('#play-progress').style.width=`${((playback.index+p)/playback.scenes.length)*100}%`;if(p>=1){nextScene();return;}}playback.raf=requestAnimationFrame(tick);}
