function endPlayback(){playback.running=false;playback.mediaGeneration++;cancelAnimationFrame(playback.raf);restoreVisuals();playback.audio?.pause();playback.audio=null;playback.audioTrip=null;document.body.classList.remove('is-playing');$('#playback').hidden=true;$('#film-ending').hidden=true;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}
function finishPlayback(){endPlayback();$('#film-ending').hidden=false;}
$('#pause-play').onclick=()=>togglePause();$('#next-play').onclick=nextScene;$('#exit-play').onclick=endPlayback;$('#fullscreen-play').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else document.documentElement.requestFullscreen().catch(()=>toast('当前窗口不支持全屏，可使用浏览器全屏。'));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(playback.running)endPlayback();$('#film-ending').hidden=true;$('#context-menu').hidden=true;}if(playback.running&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){if(e.code==='Space'){e.preventDefault();togglePause();}if(e.key==='ArrowRight'){e.preventDefault();nextScene();}}});
