document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,tid=b.dataset.trip||contextTrip,sid=b.dataset.stop||contextStop;$('#context-menu').hidden=true;try{if(a==='play')startPlayback().catch(notifyError);if(a==='finish'){$('#film-ending').hidden=true;$('#home').scrollIntoView({behavior:'smooth'});}if(a==='import')openImport();if(a==='design')openDesign();if(a==='music')openMusic(b.dataset.trip);if(a==='route')openRoute();if(a==='backup')openBackup();if(a==='note')openNote(tid,sid);if(a==='stop-note')openNote(tid,sid);if(a==='upload')chooseMedia(tid,sid);if(a==='stops')openStops(tid);if(a==='media-edit')openMediaSettings(tid,sid);}catch(e){notifyError(e);}});
